import { bandwidth, gpuCount, cpuCount, isRack, gpuMemoryLabel, memoryRateLabel } from './models.js';

const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// HTML maps keep labels and hit areas readable without scaling a 1,000-unit SVG down.
export function diagram(model, state) {
  const s = model.spec;
  const rack = isRack(s), shared = s.layout === 'shared';
  let connectionIndex = 0;
  const active = key => key.split(' ').includes(state.trace) ? 'active-path' : '';
  const card = (component, title, sub, kind = '', options = {}) => {
    const { go, node, gpu, key = title } = options;
    const identity = `${state.view}-${component}-${key}`;
    return `<button class="map-card ${kind} ${state.selected === component ? 'selected' : ''} ${gpu === state.gpu ? 'current-gpu' : ''}" data-component="${component}" data-focus-key="${esc(identity)}" ${go ? `data-go="${go}"` : ''} ${node !== undefined ? `data-node="${node}"` : ''} ${gpu !== undefined ? `data-gpu="${gpu}"` : ''}><strong>${esc(title)}${go ? '<span aria-hidden="true">↗</span>' : ''}</strong>${sub ? `<span class="map-sub">${esc(sub)}</span>` : ''}</button>`;
  };
  const connection = (component, title, kind, path) => `<div class="map-connection ${kind} ${active(path)}"><span aria-hidden="true"></span><button class="${state.selected === component ? 'selected' : ''}" data-component="${component}" data-focus-key="${state.view}-connection-${connectionIndex++}-${esc(title)}">${esc(title)}</button><span aria-hidden="true"></span></div>`;
  const gpu = i => card('gpu', `GPU ${i}`, shared ? 'Uses shared system LPDDR5X' : gpuMemoryLabel(s), 'gpu', { go: 'gpu', gpu: i });
  const fabricLabel = s.switchTrays ? `${s.switchTrays} switch trays × ${s.switchesPerTray} NVSwitch ASICs` : s.nvSwitches ? `${s.nvSwitches} NVSwitch ASICs inside this server` : 'Rack-wide switched fabric · port counts omitted';
  const hostLabel = s.hostKind === 'pcie' ? 'PCIe · host I/O' : shared ? 'C2C · coherent CPU/GPU tile connection' : 'NVLink-C2C · coherent CPU–GPU access';
  const fabric = () => card('fabric', `NVLink ${s.nvlinkGeneration} switch fabric`, `${fabricLabel}${state.labels ? ` · ${bandwidth(s.nvlinkBidirGBps / 2)} outward / GPU` : ''}`, 'gpu');
  const nicSummary = s.portSummary ? `${s.portSummary}${s.id === 'spark' ? ' · 200 Gb/s selected example' : ''}` : s.nicGbps ? `${s.nicGbps} Gb/s ${['shared', 'desktop'].includes(s.layout) ? 'adapter budget' : 'per GPU'}` : 'Rate depends on deployment';
  const io = () => `<div class="map-section-label">OTHER I/O · LOGICAL RELATIONSHIPS, LANES OMITTED</div><div class="io-grid">${card('nic', s.nicCount ? `${s.nicCount} × ${s.nicName}` : s.nicName, nicSummary, 'net')}${card('dpu', 'Storage + management', s.peripheral, 'net')}${card('storage', 'Local NVMe', s.storage, 'storage')}</div>`;

  function rackMap() {
    if (!rack) {
      const desktop = ['shared', 'desktop'].includes(s.layout);
      return `<div class="map-note">${desktop ? 'A deskside computer, not an NVL72 rack.' : 'One server is the local compute building block. Rack population is deployment-specific.'}</div><div class="domain-frame"><div class="map-section-label">${desktop ? 'ONE DESKTOP SYSTEM' : 'ONE RACKMOUNT SERVER'}</div>${card('node', s.name, `${s.cpusPerNode} host CPU${s.cpusPerNode > 1 ? 's' : ''} + ${s.gpusPerNode} GPU${s.gpusPerNode > 1 ? 's' : ''}`, 'neutral', {go:'node'})}${connection(s.nvlinkBidirGBps ? 'fabric' : 'hbm', s.nvlinkBidirGBps ? 'Local GPU peer domain' : 'Local memory stays inside this system', 'green', 'peer')}${card(s.nvlinkBidirGBps ? 'fabric' : 'hbm', s.nvlinkBidirGBps ? `${s.gpusPerNode}-GPU NVLink domain` : shared ? '128 GB shared LPDDR5X' : `${s.gpuMemoryGB} GB ${s.memoryType} + host LPDDR5X`, s.nvlinkBidirGBps ? `${s.nvSwitches} internal NVSwitches · no rack-wide NVLink` : 'One primary AI GPU · no local GPU peer', 'gpu')}</div>${connection('nic', 'Beyond the system boundary', 'blue', 'remote')}${card('network', 'External network', `${s.nicName} · separate computers retain separate memories`, 'net', {go:'cluster'})}${card('infrastructure', 'Power, cooling + management', s.cooling, 'neutral')}`;
    }
    return `<div class="map-note">Every numbered tray is a server. Select one to inspect its CPUs and GPUs.</div><div class="domain-frame ${active('peer')}"><div class="domain-heading"><strong>ONE ${gpuCount(s)}-GPU NVLINK DOMAIN</strong><span>${s.nodes} compute trays · ${cpuCount(s)} CPUs</span></div><div class="tray-grid">${Array.from({ length:s.nodes }, (_, i) => card('node', `Node ${String(i + 1).padStart(2,'0')}`, `${s.gpusPerNode} GPUs · ${s.cpusPerNode} CPUs`, `tray ${state.node === i + 1 ? 'current-node' : ''}`, {go:'node', node:i + 1})).join('')}</div>${connection('fabric', 'GPU ↔ switch fabric ↔ peer GPU', 'green', 'peer')}${fabric()}${state.labels ? `<p class="map-caption">${s.linksPerGpu ? `${s.linksPerGpu} NVLink links per GPU · one to each switch ASIC.` : 'NVLink 6 connects the rack’s GPUs. Exact switch port wiring is not depicted.'} Interface budgets are shared across peer transfers.</p>` : ''}</div>${card('infrastructure', 'Rack infrastructure', 'Power shelves · cooling · hardware management', 'neutral')}`;
  }

  function nodeMap() {
    let body = `<div class="map-note">${rack ? `Node ${String(state.node).padStart(2, '0')} of ${s.nodes}. ` : ''}${s.superchipsPerNode ? `${s.superchipsPerNode} superchip${s.superchipsPerNode > 1 ? 's' : ''} · ${s.gpusPerSuperchip} GPU${s.gpusPerSuperchip > 1 ? 's' : ''} per CPU–GPU group.` : 'x86 hosts use PCIe; peer GPUs use the internal NVLink fabric.'}</div>`;
    if (s.cpusPerNode === 2) body += connection('cpuLink', `CPU 0 ↔ CPU 1 · ${s.cpuLink}`, 'amber', 'cpuLink');
    if (s.superchipsPerNode) {
      body += `<div class="superchip-grid">${Array.from({length:s.superchipsPerNode}, (_, p) => `<section class="superchip-group"><button class="group-heading" data-component="superchip" data-focus-key="node-superchip-${p}">${s.id === 'spark' ? 'GB10' : s.id === 'station' ? 'GB300 DESKTOP' : s.id === 'rubin' ? 'VERA RUBIN' : s.id.toUpperCase()} SUPERCHIP ${s.superchipsPerNode > 1 ? p + 1 : ''}</button>${card('cpu', `${s.cpuName}${s.cpusPerNode > 1 ? ` ${p}` : ''}`, shared ? `${s.cpuCores} cores · shares system memory` : `${s.cpuCores} cores · ${s.cpuMemory}`, 'cpu', {key:`cpu-${p}`})}${connection('c2c', hostLabel, 'amber', shared ? 'c2c' : 'host')}<div class="gpu-grid ${s.gpusPerSuperchip === 1 ? 'single' : ''}">${Array.from({length:s.gpusPerSuperchip}, (_, k) => gpu(p * s.gpusPerSuperchip + k)).join('')}</div></section>`).join('')}</div>`;
    } else {
      body += `<div class="host-grid">${Array.from({length:s.cpusPerNode}, (_, i) => card('cpu', `CPU ${i} · ${s.cpuName}`, `${s.cpuMemory} across both hosts`, 'cpu', {key:`cpu-${i}`})).join('')}</div>${connection('c2c', hostLabel, 'amber', 'host')}<div class="gpu-grid server-gpus">${Array.from({length:s.gpusPerNode}, (_, i) => gpu(i)).join('')}</div>`;
    }
    if (s.totalGpuMemory) body += `<p class="map-note">Published system totals across ${s.gpusPerNode} GPUs: ${s.totalGpuMemory} HBM capacity · ${bandwidth(s.totalMemoryGBps)} summed HBM bandwidth. Individual GPU values are not separately specified by the selected DGX datasheet.</p>`;
    if (shared) body += `${connection('hbm', 'CPU and GPU use one physical memory pool', 'green', 'host memory')}${card('hbm', '128 GB shared LPDDR5X', '273 GB/s published system-memory bandwidth · count capacity once', 'gpu')}`;
    if (s.nvlinkBidirGBps) body += `<div class="map-section-label">GPU PEER PATH · INDEPENDENT OF HOST AND NIC PATHS</div>${connection('fabric', rack ? 'All four GPUs connect to rack NVSwitches' : 'All eight GPUs connect to internal NVSwitches', 'green', 'peer')}${fabric()}`;
    // NIC is explicitly attached to the GPU/I/O path, never to an NVSwitch output.
    body += `<div class="map-section-label">PARALLEL NETWORK PATH · STARTS AT GPU / HOST I/O</div>${connection('nic', s.nicConnection || 'GPU / host I/O ↔ compute NIC · separate from NVLink', 'blue', 'remote')}${io()}`;
    return body;
  }

  function gpuMap() {
    if (shared) return `<div class="map-note">GB10 combines CPU and GPU functions with a shared physical memory system.</div><div class="package-frame"><div class="map-section-label">GB10 · SHARED MEMORY MODEL</div><div class="host-grid">${card('cpu', '20-core Arm CPU', '10 Cortex-X925 + 10 Cortex-A725', 'cpu')}${card('die', 'Blackwell GPU', 'CUDA + Tensor Core compute engines', 'die')}</div>${connection('c2c', 'CPU tile ↔ coherent C2C ↔ GPU tile', 'amber', 'c2c')}${connection('hbm', 'Both processors access the same LPDDR5X', 'green', 'memory')}${card('hbm', '128 GB shared LPDDR5X', '273 GB/s published memory-interface bandwidth', 'gpu')}<p class="map-caption">There is no separate HBM pool. Capacity and bandwidth belong to the shared system interface.</p></div>${connection('nic', 'Outside the computer', 'blue', 'remote')}${card('nic', 'ConnectX-7 network adapter', nicSummary, 'net')}`;
    return `<div class="map-note">${rack ? `Node ${String(state.node).padStart(2,'0')}` : s.name} → ${s.superchipsPerNode ? `superchip ${Math.floor(state.gpu / s.gpusPerSuperchip) + 1} → ` : ''}GPU ${state.gpu}. ${rack ? `One of ${gpuCount(s)} GPUs in the rack.` : 'One logical CUDA accelerator.'}</div><div class="package-frame"><div class="domain-heading"><strong>GPU ${state.gpu} · ${esc(s.gpuName)}</strong><span>${s.computeDies} compute ${s.computeDies === 1 ? 'die' : 'dies'}</span></div>${card('hbm', s.gpuMemoryGB === null ? `Local ${s.memoryType}` : gpuMemoryLabel(s), `${memoryRateLabel(s)} · ${s.memoryQualifier || 'selected reference capacity'}`, 'gpu')}${s.totalGpuMemory ? `<p class="map-caption">The ${s.totalGpuMemory} / ${bandwidth(s.totalMemoryGBps)} published system totals span all ${s.gpusPerNode} local HBM interfaces; neither is one GPU’s individual specification.</p>` : ''}${s.hbmStacks ? `<div class="memory-stacks" aria-label="${s.hbmStacks} HBM stacks">${Array.from({length:s.hbmStacks}, (_, i) => `<span>HBM ${i}</span>`).join('')}</div>` : ''}${connection('hbm', 'Local memory controllers', 'green', 'memory')}<div class="die-grid ${s.computeDies === 1 ? 'single' : ''}">${Array.from({length:s.computeDies}, (_, i) => card('die', `Compute die ${i}`, 'Compute engines + cache', 'die', {key:`die-${i}`})).join('')}</div>${s.computeDies === 2 ? `<div class="die-bridge">↔ ${s.id === 'rubin' ? 'Internal die-to-die interface · rate not asserted' : 'NV-HBI · 10 TB/s published die-to-die bandwidth'}</div>` : ''}<p class="map-caption">Package-level logical view. Memory-stack placement and chip floorplan are not reproduced.</p></div><div class="interfaces">${card('c2c', s.hostKind === 'pcie' ? 'PCIe → x86 host' : 'NVLink-C2C → paired CPU', 'Host access · distinct from peer communication', 'cpu')}${s.nvlinkBidirGBps ? card('fabric', `NVLink ${s.nvlinkGeneration} → peer GPUs`, rack ? 'Through the rack’s switch fabric' : 'Through the server’s internal switches', 'gpu') : card('nic', `${s.nicName} → another system`, 'Network path, not a local peer NVLink', 'net', {go:'cluster'})}</div>`;
  }

  function clusterMap() {
    return `<div class="map-note">Two ${rack ? 'racks' : 'computers'} are shown as an example. Each keeps its own OS boundaries and local memories.</div><div class="cluster-pair ${active('remote')}">${['A','B'].map(letter => `<section class="domain-frame"><div class="map-section-label">${rack ? 'RACK' : 'SYSTEM'} ${letter}</div>${card('rack', `${gpuCount(s)} GPU${gpuCount(s) > 1 ? 's' : ''} · ${cpuCount(s)} CPU${cpuCount(s) > 1 ? 's' : ''}`, rack ? `${s.nodes} independent compute nodes` : s.name, 'neutral', {go:'rack', key:`system-${letter}`})}${s.nvlinkBidirGBps ? `<p class="local-domain">Local NVLink domain: ${gpuCount(s)} GPUs</p>` : '<p class="local-domain">Local CPU/GPU memory stays here</p>'}${connection('nic', 'GPU endpoint ↔ compute NIC', 'blue', 'remote')}${card('nic', s.nicName, nicSummary, 'net', {key:`nic-${letter}`})}</section>`).join('')}</div>${connection('network', 'Adapter A ↔ external fabric / direct link ↔ adapter B', 'blue', 'remote')}${card('network', ['shared','desktop'].includes(s.layout) ? 'Ethernet network / supported direct adapter link' : 'External InfiniBand or Ethernet compute fabric', 'Logical path · tiers, ports and oversubscription depend on deployment', 'net')}${state.labels && s.nicGbps ? `<p class="map-caption">${s.id === 'station' ? '50 GB/s per direction per 400 Gb/s port; 100 GB/s is the adapter sum across two ports.' : s.id === 'spark' ? '25 GB/s per direction for the selected 200 Gb/s connection; two external ports share SoC-facing I/O.' : `${bandwidth(s.nicGbps / 8)} each direction at the compute endpoint.`} These are ceilings before overhead, not measured application rates.</p>` : ''}`;
  }
  return `<div class="architecture-map map-${state.view}" role="group" aria-label="${esc(model.views[state.view].title)}">${({ rack:rackMap, node:nodeMap, gpu:gpuMap, cluster:clusterMap })[state.view]()}</div>`;
}
